 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, color, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE, textureLoader, emit } = ctx;
  const { Group, Mesh, PlaneGeometry } = THREE;

  const colors = config.intent?.visualSpec?.colors || config.visualSpec?.colors || {};
  const paperHex = colors.paper || '#e8ecf2';
  const accentHex = colors.accent || '#ff2a38';
  const surfaceHex = colors.surface || '#0b0b10';

  const root = new Group();
  root.name = config.id || 'list-row';

  const rowW = 4.2;
  const rowH = 0.68;

  const cardGeom = new PlaneGeometry(rowW, rowH);
  const cardMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 1.0 });
  cardMat.colorNode = color(surfaceHex);
  const card = new Mesh(cardGeom, cardMat);
  card.name = 'list-row-card';
  root.add(card);

  const edgeGeom = new PlaneGeometry(0.04, rowH * 0.92);
  const edgeMat = new MeshBasicNodeMaterial({ color: accentHex, transparent: true, opacity: 0.15, depthWrite: false });
  const edge = new Mesh(edgeGeom, edgeMat);
  edge.position.set(-rowW / 2 + 0.04, 0, 0.01);
  edge.name = 'list-row-accent-edge';
  root.add(edge);

  const divGeom = new PlaneGeometry(rowW * 0.94, 0.008);
  const divMat = new MeshBasicNodeMaterial({ color: paperHex, transparent: true, opacity: 0.12, depthWrite: false });
  const divider = new Mesh(divGeom, divMat);
  divider.position.set(0, -rowH / 2 + 0.035, 0.008);
  divider.name = 'list-row-divider';
  root.add(divider);

  let loadedTexture = null;
  const texPromise = textureLoader.loadTexture(config.imageUrl).then((tex) => {
    loadedTexture = tex;
    tex.wrapS = THREE.RepeatWrapping;
    tex.wrapT = THREE.RepeatWrapping;
    tex.repeat.set(2.0, 0.35);
    tex.colorSpace = THREE.SRGBColorSpace;

    const sample = texture(tex, uv());
    const brushedTint = mix(color(surfaceHex), color(paperHex), smoothstep(0.2, 0.75, sample.r).mul(0.28));
    cardMat.colorNode = brushedTint;
    cardMat.needsUpdate = true;
  }).catch(() => {
    cardMat.colorNode = color(surfaceHex);
    cardMat.needsUpdate = true;
  });

  root.userData.handlers = {};

  root.userData.handlers.pointerenter = () => {
    gsap.to(root.position, { y: 0.15, duration: 0.35, ease: 'power2.out' });
    gsap.to(edgeMat, { opacity: 0.85, duration: 0.2, ease: 'power2.out' });
    gsap.to(divMat, { opacity: 0.32, duration: 0.2, ease: 'power2.out' });
  };

  root.userData.handlers.pointerleave = () => {
    gsap.to(root.position, { y: 0, duration: 0.35, ease: 'power2.out' });
    gsap.to(root.scale, { x: 1, y: 1, z: 1, duration: 0.25, ease: 'power2.out' });
    gsap.to(edgeMat, { opacity: 0.15, duration: 0.25, ease: 'power2.out' });
    gsap.to(divMat, { opacity: 0.12, duration: 0.25, ease: 'power2.out' });
  };

  root.userData.handlers.pointerdown = () => {
    gsap.to(root.scale, { x: 0.99, y: 0.97, z: 1, duration: 0.12, ease: 'back.out(1.7)' });
  };

  root.userData.handlers.pointerup = () => {
    gsap.to(root.scale, { x: 1, y: 1, z: 1, duration: 0.12, ease: 'back.out(1.7)' });
    emit('hub-collection.select', { id: config.id });
  };

  const primitiveCleanups = [];
  const primitives = config.cinematicPrimitives || [];
  for (const p of primitives) {
    if (ctx.primitives?.[p.name]) {
      const res = ctx.primitives[p.name](root, p.params || {});
      if (res?.cleanup) primitiveCleanups.push(res.cleanup);
    }
  }

  root.userData.cleanup = () => {
    gsap.killTweensOf([root.position, root.scale, edgeMat, divMat]);
    for (const c of primitiveCleanups) if (typeof c === 'function') c();
    cardGeom.dispose();
    cardMat.dispose();
    edgeGeom.dispose();
    edgeMat.dispose();
    divGeom.dispose();
    divMat.dispose();
    texPromise.then(() => {
      if (loadedTexture) loadedTexture.dispose();
    });
  };

  return root;
}
